// 1. Domain Entities (Nouns)
class Product {
    private String id;
    private double price;
    public Product(String id, double price) { this.id = id; this.price = price; }
    public double getPrice() { return price; }
    public String getId() { return id; }
}

class CartItem {
    private Product product; // Has-A
    private int quantity;
    public CartItem(Product p, int q) { this.product = p; this.quantity = q; }
    public double getSubtotal() { return product.getPrice() * quantity; }
}

// 2. Service Orchestrator (Verb)
class CheckoutService {
    public double calculateTotal(CartItem[] items, double discountRate) {
        double total = 0;
        for (CartItem item : items) {
            total += item.getSubtotal(); // Delegation!
        }
        return total * (1.0 - discountRate);
    }
}

// 3. System Entry Point
public class StoreApp {
    public static void main(String[] args) {
        Product laptop = new Product("PROD-LAPTOP", 1200.0);
        Product mouse = new Product("PROD-MOUSE", 25.0);

        CartItem[] cart = new CartItem[] {
            new CartItem(laptop, 1),
            new CartItem(mouse, 2)
        };

        CheckoutService checkout = new CheckoutService();
        double finalTotal = checkout.calculateTotal(cart, 0.10); // 10% discount
        System.out.println("Checkout Total: $" + finalTotal);
    }
}

