class Patient {
    private String name;
    private int severityCode;
    public Patient(String name, int severityCode) {
        this.name = name;
        this.severityCode = severityCode;
    }
    public String getName() { return name; }
    public int getSeverityCode() { return severityCode; }
}

class TriageDesk {
    public void processPatient(Patient p) {
        if (p.getSeverityCode() <= 2) {
            System.out.println("URGENT: Dispatch " + p.getName() + " to Emergency Room");
        } else {
            System.out.println("STANDARD: Assign " + p.getName() + " to Waiting Lounge");
        }
    }
}

public class TriageApp {
    public static void main(String[] args) {
        Patient[] arrivals = new Patient[] {
            new Patient("John", 1),
            new Patient("Sarah", 4)
        };
        TriageDesk desk = new TriageDesk();
        for (Patient p : arrivals) {
            desk.processPatient(p);
        }
    }
}

import java.util.HashMap;
import java.util.Map;

class Account {
    private String id;
    private double balance;
    public Account(String id, double balance) {
        this.id = id;
        this.balance = balance;
    }
    public String getId() { return id; }
    public double getBalance() { return balance; }
    public void debit(double amt) { this.balance -= amt; }
    public void credit(double amt) { this.balance += amt; }
}

class AccountStorage {
    private Map<String, Account> map = new HashMap<>();
    public void save(Account acc) { map.put(acc.getId(), acc); }
    public Account find(String id) { return map.get(id); }
}

class TransferCoordinator {
    private AccountStorage storage;
    public TransferCoordinator(AccountStorage storage) {
        this.storage = storage;
    }
    public boolean transfer(String fromId, String toId, double amount) {
        Account from = storage.find(fromId);
        Account to = storage.find(toId);
        if (from != null && to != null && from.getBalance() >= amount) {
            from.debit(amount);
            to.credit(amount);
            return true;
        }
        return false;
    }
}

public class BankApp {
    public static void main(String[] args) {
        AccountStorage storage = new AccountStorage();
        Account a1 = new Account("ACC-1", 500.0);
        Account a2 = new Account("ACC-2", 200.0);
        storage.save(a1);
        storage.save(a2);

        TransferCoordinator tc = new TransferCoordinator(storage);
        boolean ok = tc.transfer("ACC-1", "ACC-2", 150.0);

        System.out.println("Transfer success: " + ok);
        System.out.println("ACC-1 balance: $" + a1.getBalance());
        System.out.println("ACC-2 balance: $" + a2.getBalance());
    }
}

