import java.util.ArrayList;
import java.util.List;

class Department {
    private String name;
    private List<Employee> staff = new ArrayList<>();
    public Department(String name) { this.name = name; }
    public void addEmployee(Employee e) { staff.add(e); }
    public String getName() { return name; }
    public void printReport() {
        System.out.println("Dept: " + name);
        for (Employee e : staff) {
            e.describe();
        }
    }
}

class Employee {
    private String name;
    private Department dept;
    public Employee(String name, Department dept) {
        this.name = name;
        this.dept = dept;
    }
    public void describe() {
        System.out.println("  Emp: " + name + " in " + dept.getName());
    }
}

public class CircularBug {
    public static void main(String[] args) {
        Department eng = new Department("Engineering");
        Employee dev = new Employee("Dave", eng);
        eng.addEmployee(dev);
        eng.printReport();
    }
}

class TelemetryReading {
    private String metric;
    private double val;
    public TelemetryReading(String metric, double val) {
        this.metric = metric;
        this.val = val;
    }
    public String getMetric() { return metric; }
    public double getVal() { return val; }
}

interface MetricFilter {
    boolean allow(TelemetryReading r);
}

class HighValueFilter implements MetricFilter {
    private double threshold;
    public HighValueFilter(double threshold) {
        this.threshold = threshold;
    }
    @Override
    public boolean allow(TelemetryReading r) {
        return r.getVal() >= threshold;
    }
}

class TelemetryIngestor {
    private MetricFilter filter;
    public TelemetryIngestor(MetricFilter filter) {
        this.filter = filter;
    }
    public int countAccepted(TelemetryReading[] stream) {
        int count = 0;
        for (TelemetryReading r : stream) {
            if (filter.allow(r)) count++;
        }
        return count;
    }
}

public class TracerApp {
    public static void main(String[] args) {
        TelemetryReading[] stream = new TelemetryReading[] {
            new TelemetryReading("CPU", 85.0),
            new TelemetryReading("CPU", 42.0),
            new TelemetryReading("CPU", 92.0)
        };
        TelemetryIngestor ingestor = new TelemetryIngestor(new HighValueFilter(80.0));
        System.out.println("Accepted high metrics: " + ingestor.countAccepted(stream));
    }
}
